"""Identity of entities generated by Adaptive Areas.

One rule derives the default entity ID and the unique ID of a generated entity. The
entity classes use it to create their identity; internal consumers use it to look up the
entity ID that the Home Assistant entity registry actually holds for that unique ID. The
registry entity ID can differ from the default one: users may rename it, and Home
Assistant appends a suffix when the default ID is already taken.
"""

from __future__ import annotations

from collections.abc import Sequence

from homeassistant.core import HomeAssistant
from homeassistant.helpers.device_registry import (
    async_entries_for_config_entry,
    async_get as async_get_device_registry,
)
from homeassistant.helpers.entity_registry import (
    RegistryEntry,
    async_entries_for_device,
    async_get as async_get_entity_registry,
)

from custom_components.adaptive_areas.const import (
    ADAPTIVE_DEVICE_ID_PREFIX,
    ADAPTIVEAREAS_UNIQUEID_PREFIX,
    DOMAIN,
    AdaptiveAreasFeatureInfo,
)


def area_device_identifier(area_id: str) -> tuple[str, str]:
    """Return the device registry identifier of one logical Area.

    It is built from the stable Area ID (Home Assistant Area, floor or Meta ID), never
    from the name, so it survives renames and cannot match a similarly named Area.
    """
    return (DOMAIN, f"{ADAPTIVE_DEVICE_ID_PREFIX}{area_id}")


def area_id_from_device_identifiers(identifiers) -> str | None:
    """Return the Area ID of an Adaptive Areas device, or None for any other device."""
    for domain, value in identifiers:
        if domain == DOMAIN and str(value).startswith(ADAPTIVE_DEVICE_ID_PREFIX):
            return str(value)[len(ADAPTIVE_DEVICE_ID_PREFIX) :]
    return None


def generated_entity_area_id(hass: HomeAssistant, entity: RegistryEntry) -> str | None:
    """Return the Area that owns a generated registry entity, or None if unknown.

    Ownership is the entity's Adaptive Areas device, whose identifier carries the stable
    Area ID. An entity of another integration, or a legacy entity without that device,
    has no unambiguous owner and returns None.
    """
    if entity.platform != DOMAIN or entity.device_id is None:
        return None
    device = async_get_device_registry(hass).async_get(entity.device_id)
    if device is None:
        return None
    return area_id_from_device_identifiers(device.identifiers)


def generated_entities_for_area_id(
    hass: HomeAssistant, config_entry_id: str, area_id: str
) -> list[RegistryEntry]:
    """Return the generated registry entities one Area owns in one config entry."""
    identifier = area_device_identifier(area_id)
    entity_registry = async_get_entity_registry(hass)
    return [
        entity
        for device in async_entries_for_config_entry(
            async_get_device_registry(hass), config_entry_id
        )
        if identifier in device.identifiers
        for entity in async_entries_for_device(
            entity_registry, device.id, include_disabled_entities=True
        )
        if entity.platform == DOMAIN and entity.config_entry_id == config_entry_id
    ]


def generated_translation_key(
    feature_info: type[AdaptiveAreasFeatureInfo] | AdaptiveAreasFeatureInfo,
    domain: str,
    translation_key: str | None = None,
) -> str:
    """Return the combined translation key of a generated entity."""
    parts = []
    if feature_key := feature_info.translation_keys[domain]:
        parts.append(feature_key)
    if translation_key:
        parts.append(translation_key)
    return "_".join(parts)


def generated_ids(
    feature_info: type[AdaptiveAreasFeatureInfo] | AdaptiveAreasFeatureInfo,
    domain: str,
    slug: str,
    translation_key: str | None = None,
    extra_identifiers: Sequence[str] | None = None,
) -> tuple[str, str]:
    """Return the default entity ID and the unique ID of a generated entity."""
    combined_key = generated_translation_key(feature_info, domain, translation_key)
    entity_parts = [ADAPTIVEAREAS_UNIQUEID_PREFIX, feature_info.id, slug]
    if combined_key and combined_key != feature_info.id:
        entity_parts.append(combined_key)
    unique_parts = [ADAPTIVEAREAS_UNIQUEID_PREFIX, feature_info.id, domain, slug]
    if combined_key:
        unique_parts.append(combined_key)
    if extra_identifiers:
        entity_parts.extend(extra_identifiers)
        unique_parts.extend(extra_identifiers)
    return f"{domain}.{'_'.join(entity_parts)}", "_".join(unique_parts)


def registered_generated_entity_id(
    hass: HomeAssistant,
    feature_info: type[AdaptiveAreasFeatureInfo] | AdaptiveAreasFeatureInfo,
    domain: str,
    slug: str,
    translation_key: str | None = None,
    extra_identifiers: Sequence[str] | None = None,
) -> str | None:
    """Return the registered entity ID of a generated entity, or None.

    A consumer that must never read another entity at the default ID uses this after
    the platforms registered their entities.
    """
    _default_entity_id, unique_id = generated_ids(
        feature_info, domain, slug, translation_key, extra_identifiers
    )
    return async_get_entity_registry(hass).async_get_entity_id(
        domain, DOMAIN, unique_id
    )


def resolve_generated_entity_id(
    hass: HomeAssistant,
    feature_info: type[AdaptiveAreasFeatureInfo] | AdaptiveAreasFeatureInfo,
    domain: str,
    slug: str,
    translation_key: str | None = None,
    extra_identifiers: Sequence[str] | None = None,
) -> str:
    """Return the registered entity ID, or the default ID while not registered yet.

    The default is the ID Home Assistant gives the entity on first registration
    unless it is already taken.
    """
    return (
        registered_generated_entity_id(
            hass, feature_info, domain, slug, translation_key, extra_identifiers
        )
        or generated_ids(
            feature_info, domain, slug, translation_key, extra_identifiers
        )[0]
    )
